import{_ as a,o as e,c as i,a2 as s}from"./chunks/framework.DtFQgA2F.js";const p=JSON.parse('{"title":"Visual Studio 编辑器","description":"","frontmatter":{"title":"Visual Studio 编辑器"},"headers":[],"relativePath":"notes/01-cpp/visual-studio.md","filePath":"notes/01-cpp/visual-studio.md","lastUpdated":null}'),d={name:"notes/01-cpp/visual-studio.md"};function l(o,t,r,n,h,c){return e(),i("div",null,[...t[0]||(t[0]=[s(`<h1 id="visual-studio-编辑器" tabindex="-1">Visual Studio 编辑器 <a class="header-anchor" href="#visual-studio-编辑器" aria-label="Permalink to &quot;Visual Studio 编辑器&quot;">​</a></h1><p>C++ 开发的主力环境。本机已安装 <strong>VS 2022 Build Tools</strong>（命令行编译），完整 IDE 用 Community 版（个人免费）。</p><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h2><ul><li><strong>IDE</strong>：官网下载 Visual Studio 2022 Community，勾选「使用 C++ 的桌面开发」工作负载</li><li><strong>仅编译</strong>（命令行/CI）：<code>winget install Microsoft.VisualStudio.2022.BuildTools</code>，加装 C++ 工作负载后自带 <code>cl.exe</code> + MSBuild + CMake</li></ul><h2 id="项目形态" tabindex="-1">项目形态 <a class="header-anchor" href="#项目形态" aria-label="Permalink to &quot;项目形态&quot;">​</a></h2><table tabindex="0"><thead><tr><th>形态</th><th>说明</th><th>本项目</th></tr></thead><tbody><tr><td>.sln 解决方案</td><td>VS 原生工程文件</td><td>—</td></tr><tr><td>CMake 项目</td><td>用 <code>CMakeLists.txt</code> 描述构建，VS 直接打开目录</td><td><code>demos/phase1-GLM</code>、<code>tools/publisher-cpp</code></td></tr></tbody></table><p>命令行构建（不依赖 IDE）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --preset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vs2022</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build/vs2022</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Release</span></span></code></pre></div><h2 id="常用快捷键" tabindex="-1">常用快捷键 <a class="header-anchor" href="#常用快捷键" aria-label="Permalink to &quot;常用快捷键&quot;">​</a></h2><table tabindex="0"><thead><tr><th>快捷键</th><th>作用</th></tr></thead><tbody><tr><td>F5</td><td>启动调试</td></tr><tr><td>Ctrl+F5</td><td>运行不调试</td></tr><tr><td>Ctrl+B / F7</td><td>生成</td></tr><tr><td>F9</td><td>断点</td></tr><tr><td>F10 / F11</td><td>单步跳过 / 单步进入</td></tr><tr><td>Shift+F11</td><td>跳出当前函数</td></tr><tr><td>Ctrl+K Ctrl+C</td><td>注释选中行</td></tr><tr><td>Ctrl+K Ctrl+D</td><td>格式化文档</td></tr><tr><td>F12</td><td>跳转到定义</td></tr></tbody></table><h2 id="关键设置" tabindex="-1">关键设置 <a class="header-anchor" href="#关键设置" aria-label="Permalink to &quot;关键设置&quot;">​</a></h2><ul><li><strong>编码</strong>：源码统一 UTF-8，CMake 里对 MSVC 加 <code>/utf-8</code>，否则中文字符串乱码甚至编译报错</li><li><strong>警告等级</strong>：至少 <code>/W4</code>，配合 <code>-WX</code> 把警告当错误</li><li><strong>架构</strong>：确认选 x64（x86 下 32 位指针和整型会带来隐蔽 bug）</li></ul><h2 id="调试技巧-图形学常用" tabindex="-1">调试技巧（图形学常用） <a class="header-anchor" href="#调试技巧-图形学常用" aria-label="Permalink to &quot;调试技巧（图形学常用）&quot;">​</a></h2><ol><li><strong>断点 + 监视</strong>：把 <code>vec3</code> 等变量加进监视窗口，展开看分量</li><li><strong>条件断点</strong>：循环几百万次时按条件中断（如 <code>x == 255</code>）</li><li><strong>即时窗口</strong>：断点处随手执行表达式验证猜想</li><li><strong>内存窗口</strong>：看缓冲区的原始字节，排查像素/坐标错位</li><li><strong>把像素涂纯色</strong>：输出纯红/纯绿图片，一眼看出坐标与循环边界是否正确（见<a href="/CG/notes/03-renderer/renderer.html">渲染器原理</a>踩坑）</li></ol><h2 id="踩坑记录" tabindex="-1">踩坑记录 <a class="header-anchor" href="#踩坑记录" aria-label="Permalink to &quot;踩坑记录&quot;">​</a></h2><ul><li>Debug 与 Release 行为差异：Debug 变量初始化为特定模式、STL 越界检查会触发断言；性能测试只在 Release 做</li><li>中文路径 + 旧工具链可能出问题：工程路径保持纯 ASCII（本项目 <code>E:\\Github\\CG</code> 即如此）</li><li>修改 CMakeLists 后 VS 里的 CMake 缓存可能过期：重新配置（或删 build 目录重来）</li></ul>`,16)])])}const k=a(d,[["render",l]]);export{p as __pageData,k as default};
